import{_ as s,o as a,c as i,ag as d}from"./chunks/framework.C9sp7nFj.js";const r="/images/movh-spiral.png",c=JSON.parse('{"title":"MovH 螺旋线运动","description":"","frontmatter":{},"headers":[],"relativePath":"3. 指令/1. 运动指令/MovH.md","filePath":"3. 指令/1. 运动指令/MovH.md","lastUpdated":1778862643000}'),o={name:"3. 指令/1. 运动指令/MovH.md"};function n(e,t,l,h,p,g){return a(),i("div",null,[...t[0]||(t[0]=[d('<h1 id="movh-螺旋线运动" tabindex="-1">MovH 螺旋线运动 <a class="header-anchor" href="#movh-螺旋线运动" aria-label="Permalink to &quot;MovH 螺旋线运动&quot;">​</a></h1><p><strong>MovH</strong> 为螺旋线运动指令。该指令使机器人的 TCP 点从当前位置开始，沿着特定的螺旋路径运动到目标位置。如果起点和终点的姿态不同，机器人的姿态将在运动过程中随位置同步旋转，最终过渡到终点姿态。</p><h2 id="运动逻辑" tabindex="-1">运动逻辑 <a class="header-anchor" href="#运动逻辑" aria-label="Permalink to &quot;运动逻辑&quot;">​</a></h2><ul><li><strong>起点</strong>：上一步运动指令的终点。</li><li><strong>平面与方向</strong>：由起点、辅助点 <strong>A</strong> 和目标点 <strong>P</strong> 三点共同确定螺旋运动的平面及旋进方向（顺时针或逆时针）。</li><li><strong>轨迹特征</strong>：机器人并不一定会经过辅助点 A，而是以设定的半径 <strong>R</strong> 和步进距离 <strong>S</strong> 向终点旋进。</li></ul><hr><h2 id="指令格式" tabindex="-1">指令格式 <a class="header-anchor" href="#指令格式" aria-label="Permalink to &quot;指令格式&quot;">​</a></h2><p><code>MovH(A, P, [V], [B], [C], [Tool], [Coord], [PayLoad], R, S, [DO])</code></p><p><code>MovH(中间点, 目标点, [速度], [平滑], [姿态], [工具], [坐标系], [负载], 螺旋半径, 螺距, [端口输出])</code></p><p><em>(备注：带 [] 参数为可选参数)</em></p><hr><h2 id="参数详细说明" tabindex="-1">参数详细说明 <a class="header-anchor" href="#参数详细说明" aria-label="Permalink to &quot;参数详细说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>说明</th><th>默认值/备注</th></tr></thead><tbody><tr><td>A</td><td>APOS 或 CPOS 变量</td><td>辅助点，用于确定螺旋平面和旋进方向。</td><td>必填</td></tr><tr><td>P</td><td>APOS 或 CPOS 变量</td><td>坐标系下的最终目标位置。</td><td>必填</td></tr><tr><td>[V]</td><td>SPEED 变量</td><td>指定机器人执行螺旋运动的速度。螺旋线的最大轨迹线速度限制为系统最大速度的 <strong>0.25 倍</strong>。</td><td>可选</td></tr><tr><td>[B] &amp; [C]</td><td>-</td><td><strong>MovH 指令不支持过渡运动</strong>。参数 [B] 需设为 <code>FINE</code>，参数 [C] 不起作用。</td><td>可选</td></tr><tr><td>[Tool]</td><td>TOOL 变量</td><td>机器人执行该轨迹时使用的工具参数。</td><td>可选，默认使用当前系统中设置的工具参数</td></tr><tr><td>[Coord]</td><td>USERCOOR 变量</td><td>机器人执行该轨迹时使用的用户坐标系。</td><td>可选，默认使用当前系统中设置的坐标系参数</td></tr><tr><td>[PayLoad]</td><td>PAYLOAD 变量</td><td>机器人执行该轨迹时使用的工件负载参数。</td><td>可选，默认使用当前系统中设置的负载参数</td></tr><tr><td>R</td><td>real</td><td>螺旋线的半径（单位：mm）。</td><td>必填</td></tr><tr><td>S</td><td>real</td><td>螺旋旋转一周（360°）后，沿起终点矢量方向移动的位移距离（单位：mm）。</td><td>必填</td></tr><tr><td>[DO]</td><td>string</td><td>运动完成后触发的 IO 指令（如 <code>SetDO</code>、<code>PulseOut</code> 等）。</td><td>可选</td></tr></tbody></table><p><img src="'+r+`" alt=""></p><hr><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h2><ol><li><strong>不支持过渡</strong>：该指令执行时会自动打断路径过渡。</li><li><strong>不支持 WaitFinish</strong>：指令执行逻辑较为独立。</li></ol><hr><h2 id="应用示例" tabindex="-1">应用示例 <a class="header-anchor" href="#应用示例" aria-label="Permalink to &quot;应用示例&quot;">​</a></h2><p><strong>指令代码：</strong></p><div class="language-estun vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">estun</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">MovL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (P1, V50, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;RELATIVE&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, C50)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">MovH</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (P2, P3, V100, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;FINE&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">nullTool</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">World</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, PayLoad0, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">10</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p><strong>执行过程解析：</strong></p><ol><li>机器人首先运动到 <strong>P1</strong> 点。</li><li>以 <strong>P1</strong> 为起点，参考 <strong>P1、P2、P3</strong> 确定的平面开始螺旋运动。</li><li><strong>螺旋参数</strong>：半径为 <strong>10mm</strong>，每旋绕一圈向前进 <strong>5mm</strong>。</li><li><strong>方向控制</strong>：由 P2 点的位置决定是顺时针还是逆时针旋进。</li><li><strong>终点</strong>：最终到达 <strong>P3</strong> 点完成螺旋动作。</li></ol>`,22)])])}const E=s(o,[["render",n]]);export{c as __pageData,E as default};
